pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 value1, uint256 value2, uint256 unlock1, uint256 unlock2, uint8 actorSeed1, uint8 actorSeed2, uint8 collectIdx) public {
        // restrict to admissible domain: values within reasonable range, b not larger than type(uint256).max
        vm.assume(value1 <= type(uint128).max);
        vm.assume(value2 <= type(uint128).max);
        // compute two distinct addresses
        address actor1 = address(uint160(uint256(keccak256(abi.encode(actorSeed1)))));
        address actor2 = address(uint160(uint256(keccak256(abi.encode(actorSeed2)))));
        vm.assume(actor1 != actor2);
        vm.assume(actor1 != address(0));
        vm.assume(actor2 != address(0));

        // fund actors
        vm.deal(actor1, type(uint128).max);
        vm.deal(actor2, type(uint128).max);

        // actors call Put
        vm.prank(actor1);
        c.Put{value: value1}(unlock1);
        vm.prank(actor2);
        c.Put{value: value2}(unlock2);

        // total Ether sent to c
        uint256 totalSent = value1 + value2;

        // total balances stored in c
        uint256 totalBal = c.Acc(actor1).balance + c.Acc(actor2).balance;

        // contract Ether balance
        uint256 contractBal = address(c).balance;

        // general property: total recorded balances do not exceed total Ether sent, and contract holds at least total recorded balances
        assertTrue(totalBal <= totalSent && totalBal <= contractBal);
    }
}

